function collectBuildForm(){const get=id=>document.getElementById(id)?.value||'',context={sameElement:n(get('ctx-same')),favonius:n(get('ctx-fav'))};document.querySelectorAll('[data-build-context]').forEach(field=>{if(field.dataset.buildContext)context[field.dataset.buildContext]=field.value});return{weaponName:get('build-weapon'),artifactSet:get('build-artifact-set'),mainStats:{sands:get('main-sands'),goblet:get('main-goblet'),circlet:get('main-circlet')},context,stats:{cr:n(get('stat-cr'),NaN),cd:n(get('stat-cd'),NaN),er:n(get('stat-er'),NaN),em:n(get('stat-em'),NaN),hp:n(get('stat-hp'),NaN),atk:n(get('stat-atk'),NaN),def:n(get('stat-def'),NaN)}}}
function evaluateCurrentBuild(save=false){const id=state.ui.buildCharacterId,character=catalog?.characters.find(c=>String(c.id)===String(id));if(!character||!characterDetail)return toast('Choose a character first.');const form=collectBuildForm(),profile=resolvedBuildProfile(characterDetail,form.context),owned=state.weapons.filter(w=>sameWeaponType(w,character.weapon)),ownedEntry=owned.find(w=>w.name===form.weaponName),catalogWeapon=(buildRuntime.weaponRanks||[]).find(w=>w.name===form.weaponName)||catalog?.weapons?.find(w=>w.name===form.weaponName)||null,weapon=catalogWeapon?{...catalogWeapon,...(ownedEntry?{owned:true,ownedLevel:ownedEntry.level,ownedRefinement:ownedEntry.refinement}:{} )}:ownedEntry||null,artifactSet=catalog.artifacts.find(a=>a.name===form.artifactSet)||null;buildRuntime.formDraft={characterId:String(id),...form};latestBuildResult=evaluateBuild({profile,stats:form.stats,mainStats:form.mainStats,context:form.context,weapon,artifactSet,ownedWeapons:owned});if(save){state.builds=upsertBy(state.builds,{id:String(id),characterId:String(id),characterName:character.name,...form,profileSource:profile.profileSource,buildVariant:profile.activeVariant?.id||'',score:latestBuildResult.score,updatedAt:new Date().toISOString()});const roster=rosterEntry(id);if(roster&&form.context?.buildVariant){state.roster=upsertBy(state.roster,{...roster,buildVariant:form.context.buildVariant})}persist();toast('Build saved.')}else toast('Build evaluated.');render()}
function buildResultView(result){const next=result.nextActions?.[0];return`<section class="section card"><div class="section-head"><div class="score-wrap"><div class="score-big">${result.score}</div><div><h2>${esc(result.grade)} build</h2><p class="muted small">${esc(result.biggestImprovement)}</p></div></div><span class="pill ${result.profileSource==='reviewed'?'good':'warn'}">${esc(result.confidenceLabel||'Inferred')}</span></div>${result.activeVariant?`<div class="notice info"><strong>${esc(result.activeVariant.name)}</strong> · ${esc(result.analysisSource)}</div>`:''}<div class="progress"><i style="width:${result.score}%"></i></div><div class="section status-grid">${Object.entries(result.checks).map(([key,c])=>`<div class="status-box"><strong>${key.toUpperCase()}</strong><span class="state-${c.state}">${esc(c.label)}</span></div>`).join('')}</div>${next?`<div class="section notice ${next.progression==='Guaranteed'?'good':'info'}"><strong>Best next upgrade · ${esc(next.impact)} impact</strong><br>${esc(next.message)}<br><span class="muted small">${esc(next.progression)} progression · ${esc(next.source)}</span></div>`:''}${result.issues.length?`<div class="section"><h3>Priority improvements</h3><div class="list">${result.issues.map(i=>`<div class="list-row"><div class="row-main"><div class="row-title">${esc(i.stat)}</div><div class="row-sub">${esc(i.message)}</div></div><span class="pill gray">${esc(i.progression)}</span></div>`).join('')}</div></div>`:''}</section>`}
