function view(){if(state.ui.tab==='characters')return charactersView();if(state.ui.tab==='build')return buildView();if(state.ui.tab==='roster')return rosterView();if(state.ui.tab==='more')return moreView();return homeView()}
function render(){$app.innerHTML=`${topbar()}${view()}${nav()}`}

function generateSmartTeam(){
  if(!catalog)return;
  const normalized=sortRoster(normalizeRoster(state.roster,catalog.characters)),mode=state.ui.teamMode||'roster',locks=[];
  if(mode==='lock1'||mode==='lock2')locks.push(state.ui.teamLock1||'');
  if(mode==='lock2')locks.push(state.ui.teamLock2||'');
  const cleanLocks=locks.filter(Boolean);
  if(mode!=='roster'&&!cleanLocks.length){teamRuntime={result:null,error:'Choose a character to build around.'};render();return}
  if(mode==='lock2'&&(cleanLocks.length<2||cleanLocks[0]===cleanLocks[1])){teamRuntime={result:null,error:'Choose two different roster characters for the 2-character lock.'};render();return}
  teamRuntime={error:'',result:matchReviewedTeams({roster:normalized,lockedNames:cleanLocks,allowUnowned:Boolean(state.ui.teamAllowUnowned),limit:5})};render();
}

async function generateSmartFarmPlan(){
  if(!catalog||farmRuntime.loading)return;
  state.ui.farmServer=document.getElementById('farm-server')?.value||state.ui.farmServer||'Asia';
  state.ui.farmResin=Math.min(RESIN_CAP,Math.max(0,n(document.getElementById('farm-resin')?.value,RESIN_CAP)));
  state.ui.weeklyDiscountedClaimsUsed=Math.max(0,n(document.getElementById('farm-weekly-claims')?.value,0));persist();
  const active=sortRoster(normalizeRoster(state.roster,catalog.characters)).filter(entry=>entry.status!=='Not Building'&&entry.status!=='Finished');
  farmRuntime={loading:true,plan:null,error:''};render();
  try{
    const entries=[];
    for(let i=0;i<active.length;i+=3){
      const batch=active.slice(i,i+3),results=await Promise.allSettled(batch.map(async entry=>{const character=catalog.characters.find(c=>String(c.id)===String(entry.id));if(!character)return null;const detail=await getCharacterDetail(character),profile=resolvedBuildProfile(detail,{buildVariant:entry.buildVariant}),weapon=state.weapons.find(w=>String(w.id)===String(entry.weaponId))||null;return{entry:{...entry,name:character.name},character,detail,profile,weapon}}));
      results.forEach(result=>{if(result.status==='fulfilled'&&result.value)entries.push(result.value)});
    }
    farmRuntime={loading:false,error:'',plan:buildSmartFarmPlan({entries,inventory:state.inventory,resin:state.ui.farmResin,weeklyDiscountedClaimsUsed:state.ui.weeklyDiscountedClaimsUsed,knownMapNames:getMapFilterOptions('All')})};
  }catch(error){farmRuntime={loading:false,plan:null,error:`Could not build the farm plan: ${error.message}`}}
  render();
}

async function loadDetail(character,loadRanks=true){try{characterDetail=await getCharacterDetail(character);const saved=state.builds.find(x=>String(x.characterId)===String(character.id))||{},draft=buildDraftFor(character.id,saved),profile=resolvedBuildProfile(characterDetail,draft.context||{});buildRuntime.artifactRanks=rankArtifactSets(catalog?.artifacts||[],profile);if(loadRanks){buildRuntime.loadingWeapons=true;render();buildRuntime.weaponCandidates=await hydrateWeaponCandidates(characterDetail,14);buildRuntime.weaponRanks=rankWeapons(buildRuntime.weaponCandidates,profile,ownedWeaponNames());buildRuntime.loadingWeapons=false}render()}catch(error){buildRuntime.loadingWeapons=false;toast(`Could not load character detail: ${error.message}`);render()}}
function openCharacter(id,openBuild=false){state.ui.characterId=String(id);state.ui.tab='characters';state.ui.characterSection=openBuild?'build':(state.ui.characterSection||'build');characterDetail=null;buildRuntime={weaponCandidates:[],weaponRanks:[],artifactRanks:[],loadingWeapons:false,formDraft:null};persist();render();scrollTo({top:0,behavior:'instant'})}
function showModal(title,body){$modal.innerHTML=`<div class="modal-backdrop" data-action="close-modal"><div class="modal" onclick="event.stopPropagation()"><div class="modal-head"><h2>${esc(title)}</h2><button class="ghost" data-action="close-modal">Close</button></div>${body}</div></div>`}
function closeModal(){$modal.innerHTML=''}
function rosterModal(entry=null,selectedId=''){const options=(catalog?.characters||[]).slice().sort((a,b)=>a.name.localeCompare(b.name)),isEditing=!!entry?.id&&!!state.roster.find(x=>String(x.id)===String(entry.id)),selectedCharacter=options.find(c=>String(c.id)===String(selectedId||entry?.id))||options[0]||{},normalized=normalizeRosterEntry(entry||{id:selectedCharacter.id,name:selectedCharacter.name},selectedCharacter),weaponOptions=state.weapons.filter(w=>sameWeaponType(w,selectedCharacter.weapon)),reviewed=reviewedBuildProfile(selectedCharacter.name),variants=reviewed?.variants||[];showModal(isEditing?'Edit roster character':'Add roster character',`<div class="field"><label>Character</label><select id="modal-char" ${isEditing?'disabled':''}>${options.map(c=>`<option value="${esc(c.id)}" ${String(c.id)===String(selectedCharacter.id)?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="form-grid section"><div class="field"><label>Build status</label><select id="modal-status">${ROSTER_STATUSES.map(x=>`<option ${x===normalized.status?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Priority</label><select id="modal-priority">${ROSTER_PRIORITIES.map(x=>`<option ${x===normalized.priority?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Current level</label><input id="modal-level" type="number" min="1" max="90" value="${normalized.level}" /></div><div class="field"><label>Current ascension</label><input id="modal-ascension" type="number" min="0" max="6" value="${normalized.ascension}" /></div><div class="field"><label>Constellation</label><input id="modal-c" type="number" min="0" max="6" value="${normalized.constellation}" /></div><div class="field"><label>Equipped owned weapon</label><select id="modal-equipped-weapon"><option value="">Not selected</option>${weaponOptions.map(w=>`<option value="${esc(w.id)}" ${String(w.id)===String(normalized.weaponId)?'selected':''}>${esc(w.name)} · Lv ${n(w.level,1)} · R${n(w.refinement,1)}</option>`).join('')}</select></div></div><div class="section"><h3>Current talents</h3><div class="form-grid"><div class="field"><label>Normal Attack</label><input id="modal-talent-attack" type="number" min="1" max="15" value="${normalized.talents.attack}" /></div><div class="field"><label>Skill</label><input id="modal-talent-skill" type="number" min="1" max="15" value="${normalized.talents.skill}" /></div><div class="field"><label>Burst</label><input id="modal-talent-burst" type="number" min="1" max="15" value="${normalized.talents.burst}" /></div></div></div><div class="section"><h3>Build goals</h3><div class="form-grid"><div class="field"><label>Target level</label><input id="modal-target-level" type="number" min="1" max="90" value="${normalized.targetLevel}" /></div><div class="field"><label>Target ascension</label><input id="modal-target-ascension" type="number" min="0" max="6" value="${normalized.targetAscension}" /></div><div class="field"><label>Target weapon level</label><input id="modal-target-wlevel" type="number" min="1" max="90" value="${normalized.targetWeaponLevel}" /></div><div class="field"><label>Build profile</label><select id="modal-build-variant"><option value="">${reviewed?'Recommended default':'Automatic / inferred'}</option>${variants.map(v=>`<option value="${esc(v.id)}" ${v.id===normalized.buildVariant?'selected':''}>${esc(v.name)}</option>`).join('')}</select></div><div class="field"><label>Target Normal Attack</label><input id="modal-target-attack" type="number" min="1" max="15" value="${normalized.targetTalents.attack}" /></div><div class="field"><label>Target Skill</label><input id="modal-target-skill" type="number" min="1" max="15" value="${normalized.targetTalents.skill}" /></div><div class="field"><label>Target Burst</label><input id="modal-target-burst" type="number" min="1" max="15" value="${normalized.targetTalents.burst}" /></div></div></div><div class="field section"><label>Notes</label><textarea id="modal-roster-notes" placeholder="Optional build or farming note">${esc(normalized.notes)}</textarea></div><button class="primary section" data-action="save-roster-modal">Save character</button>`)}
function weaponModal(){const options=(catalog?.weapons||[]).slice().sort((a,b)=>a.name.localeCompare(b.name));showModal('Add owned weapon',`<div class="field"><label>Weapon</label><select id="modal-weapon">${options.map(w=>`<option value="${esc(w.id)}">${esc(w.name)} · ${w.rarity}★ · ${esc(w.weapon)}</option>`).join('')}</select></div><div class="form-grid section"><div class="field"><label>Level</label><input id="modal-wlevel" type="number" min="1" max="90" value="90" /></div><div class="field"><label>Refinement</label><input id="modal-refine" type="number" min="1" max="5" value="1" /></div></div><button class="primary section" data-action="save-weapon-modal">Save weapon</button>`)}
function uidModal(){showModal('Import public showcase',`<div class="notice info">Enka can only import characters currently exposed in your Genshin Character Showcase. It cannot read your full account inventory.</div><div class="field section"><label>Genshin UID</label><input id="uid-input" inputmode="numeric" placeholder="e.g. 800123456" value="${esc(state.uid||'')}" /></div><button class="primary" data-action="import-uid">Import with Enka</button><div class="section"><div class="field"><label>Manual Enka JSON fallback</label><textarea id="enka-json" placeholder="Paste the JSON response here if browser/API restrictions block direct import."></textarea></div><button class="secondary section" data-action="import-enka-json">Import pasted JSON</button></div>`)}
function sourceInfoModal(){showModal('Hotaru data architecture',`<div class="list"><div class="list-row"><div><div class="row-title">Hakush / Nanoka</div><div class="row-sub">Version-aware released character, weapon, artifact and material data.</div></div><span class="pill good">Primary</span></div><div class="list-row"><div><div class="row-title">Enka.Network</div><div class="row-sub">Public player showcase + metadata enrichment. Never cached by Hotaru's service worker.</div></div><span class="pill">Optional</span></div><div class="list-row"><div><div class="row-title">genshin.dev</div><div class="row-sub">Fallback static data when the current-source endpoint is unavailable.</div></div><span class="pill gray">Fallback</span></div><div class="list-row"><div><div class="row-title">Hotaru Build Intelligence</div><div class="row-sub">Deterministic kit-fit heuristics. Not official game data or a damage simulator.</div></div><span class="pill warn">Guidance</span></div></div>`)}
async function doUIDImport(dataOverride=null){try{const uid=document.getElementById('uid-input')?.value||state.uid;if(!dataOverride&&!validateUID(uid))return toast('Enter a valid 9–10 digit UID.');const result=dataOverride?parseShowcase(dataOverride,uid):await importShowcase(uid);state.uid=result.uid||uid;result.roster.forEach(entry=>{state.roster=upsertBy(state.roster,entry);if(entry.equippedWeaponId){const w=catalog?.weapons?.find(item=>String(item.id)===String(entry.equippedWeaponId));if(w)state.weapons=upsertBy(state.weapons,{id:String(w.id),name:w.name,type:w.weapon,rarity:w.rarity,level:entry.equippedWeaponLevel||1,refinement:entry.equippedWeaponRefinement||1,source:'Enka showcase'},'id')}});state.roster=normalizeRoster(state.roster,catalog?.characters||[]);persist();closeModal();toast(`Imported ${result.roster.length} showcased character${result.roster.length===1?'':'s'}.`);render()}catch(error){toast(error.message)}}
function exportBackup(){const blob=new Blob([exportState(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`hotaru-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);toast('Backup downloaded.')}

document.addEventListener('click',async event=>{
  const tab=event.target.closest('[data-tab]');if(tab)return setTab(tab.dataset.tab);const go=event.target.closest('[data-go]');if(go)return setTab(go.dataset.go);const char=event.target.closest('[data-character]');if(char)return openCharacter(char.dataset.character,!!char.dataset.openBuild);const page=event.target.closest('[data-page]');if(page){state.ui.page=n(page.dataset.page,1);persist();render();scrollTo({top:0,behavior:'instant'});return}const section=event.target.closest('[data-char-section]');if(section){state.ui.characterSection=section.dataset.charSection;persist();render();return}const removeW=event.target.closest('[data-remove-weapon]');if(removeW){state.weapons.splice(Number(removeW.dataset.removeWeapon),1);persist();render();return}
  const action=event.target.closest('[data-action]')?.dataset.action;if(!action)return;
  if(action==='close-modal')return closeModal();if(action==='back-characters'){state.ui.characterId='';characterDetail=null;persist();render();return}
  if(action==='toggle-haptics'){state.settings.haptics=!state.settings.haptics;persist();render();toast(`Haptics ${state.settings.haptics?'on':'off'}.`);return}
  if(action==='refresh-catalog'){sourceStatus='loading';render();try{catalog=await refreshCatalog();sourceStatus=catalog.warning?'warn':'ready';toast('Game data refreshed.')}catch(e){sourceStatus='error';toast(e.message)}render();return}
  if(action==='toggle-roster'){const id=event.target.closest('[data-id]')?.dataset.id,entry=rosterEntry(id);if(entry)return rosterModal(entry);const c=catalog.characters.find(x=>String(x.id)===String(id));state.roster=upsertBy(state.roster,normalizeRosterEntry({id:String(id),name:c?.name||'',level:1,constellation:0,source:'Manual'},c||{}));persist();toast('Added to roster.');render();return}
  if(action==='use-build'){const id=event.target.closest('[data-id]')?.dataset.id;state.ui.buildCharacterId=String(id);state.ui.tab='build';state.ui.characterId='';characterDetail=null;latestBuildResult=null;persist();render();return}
  if(action==='generate-smart-team')return generateSmartTeam();
  if(action==='generate-smart-farm')return generateSmartFarmPlan();
  if(action==='evaluate-build')return evaluateCurrentBuild(false);if(action==='save-build')return evaluateCurrentBuild(true);
  if(action==='evaluate-artifact'){if(!characterDetail)return;const formContext=buildRuntime.formDraft?.context||state.builds.find(x=>String(x.characterId)===String(state.ui.buildCharacterId))?.context||{},profile=resolvedBuildProfile(characterDetail,formContext),gv=id=>n(document.getElementById(id)?.value,0),result=scoreArtifact({profile,mainStat:document.getElementById('artifact-main')?.value||'',substats:{cr:gv('artifact-cr'),cd:gv('artifact-cd'),er:gv('artifact-er'),em:gv('artifact-em'),scaling:gv('artifact-scaling')}}),box=document.getElementById('artifact-result');if(box)box.innerHTML=`<div class="section notice good"><strong>${result.grade} · ${result.score}/100</strong><br>CRIT Value: ${result.critValue}<br>${esc(result.note)}</div>`;state.artifacts.push({characterId:String(state.ui.buildCharacterId),score:result.score,checkedAt:new Date().toISOString()});state.artifacts=state.artifacts.slice(-100);persist();return}
  if(action==='add-roster-modal')return rosterModal();if(action==='edit-roster')return rosterModal(rosterEntry(event.target.closest('[data-id]')?.dataset.id));
  if(action==='save-roster-modal'){const id=document.getElementById('modal-char')?.value||document.getElementById('modal-char')?.selectedOptions?.[0]?.value;if(!id)return;const c=catalog.characters.find(x=>String(x.id)===String(id)),previous=rosterEntry(id)||{};const entry=normalizeRosterEntry({...previous,id:String(id),name:c?.name||'',level:n(document.getElementById('modal-level')?.value,1),ascension:n(document.getElementById('modal-ascension')?.value,0),constellation:n(document.getElementById('modal-c')?.value,0),talents:{attack:n(document.getElementById('modal-talent-attack')?.value,1),skill:n(document.getElementById('modal-talent-skill')?.value,1),burst:n(document.getElementById('modal-talent-burst')?.value,1)},status:document.getElementById('modal-status')?.value||'Not Building',priority:document.getElementById('modal-priority')?.value||'Medium',weaponId:document.getElementById('modal-equipped-weapon')?.value||'',targetLevel:n(document.getElementById('modal-target-level')?.value,90),targetAscension:n(document.getElementById('modal-target-ascension')?.value,6),targetWeaponLevel:n(document.getElementById('modal-target-wlevel')?.value,90),targetTalents:{attack:n(document.getElementById('modal-target-attack')?.value,9),skill:n(document.getElementById('modal-target-skill')?.value,9),burst:n(document.getElementById('modal-target-burst')?.value,9)},buildVariant:document.getElementById('modal-build-variant')?.value||'',notes:document.getElementById('modal-roster-notes')?.value||'',source:previous.source||'Manual'},c||{});state.roster=upsertBy(state.roster,entry);persist();closeModal();toast('Roster updated.');render();return}
  if(action==='add-weapon-modal')return weaponModal();if(action==='save-weapon-modal'){const id=document.getElementById('modal-weapon')?.value,w=catalog.weapons.find(x=>String(x.id)===String(id));if(!w)return;state.weapons=upsertBy(state.weapons,{id:String(id),name:w.name,type:w.weapon,rarity:w.rarity,level:Math.min(90,Math.max(1,n(document.getElementById('modal-wlevel')?.value,90))),refinement:Math.min(5,Math.max(1,n(document.getElementById('modal-refine')?.value,1)))},'id');persist();closeModal();toast('Weapon saved.');render();return}
  if(action==='uid-modal')return uidModal();if(action==='import-uid')return doUIDImport();if(action==='import-enka-json'){try{return doUIDImport(JSON.parse(document.getElementById('enka-json')?.value||'{}'))}catch{return toast('Invalid JSON.')}}
  if(action==='export-data')return exportBackup();if(action==='source-info')return sourceInfoModal();
});
function refreshCharacterSearchResults(){
  if(state.ui.tab!=='characters'||state.ui.characterId||!catalog)return;
  const main=$app.querySelector('main'),input=main?.querySelector('#character-search');if(!input)return;
  const all=filteredCharacters(),perPage=24,pages=Math.max(1,Math.ceil(all.length/perPage));state.ui.page=Math.min(pages,Math.max(1,n(state.ui.page,1)));const page=state.ui.page,shown=all.slice((page-1)*perPage,page*perPage),grid=main.querySelector('.grid.auto'),pagination=main.querySelector('.pagination'),count=main.querySelector('.section-head .muted.small');
  if(grid)grid.innerHTML=shown.map(c=>`<button class="card character-card" data-character="${esc(c.id)}"><div class="character-art">${image(c.icon,c.name)}</div><div class="character-info"><div class="character-name">${esc(c.name)}</div><div class="character-meta"><span>${esc(c.element)}</span><span>·</span><span>${esc(c.weapon)}</span><span>·</span><span>${safeCharacterRarity(c.rarity,4)}★</span></div></div></button>`).join('')||`<div class="card empty"><div class="empty-symbol">⌕</div><h3>No matches</h3><p>Try another filter.</p></div>`;
  if(pagination)pagination.innerHTML=`<button class="secondary" data-page="${page-1}" ${page<=1?'disabled':''}>Previous</button><span>${page} / ${pages}</span><button class="secondary" data-page="${page+1}" ${page>=pages?'disabled':''}>Next</button>`;
  if(count)count.textContent=`${all.length} matching characters`;
  document.dispatchEvent(new CustomEvent('hotaru:character-search-updated',{detail:{query:state.ui.search,page}}));
}
document.addEventListener('input',event=>{if(event.target?.id==='character-search'){state.ui.search=event.target.value;state.ui.page=1;persist();clearTimeout(window.__hotaruSearch);window.__hotaruSearch=setTimeout(refreshCharacterSearchResults,70)}})
function refreshBuildContext(){if(!characterDetail||!state.ui.buildCharacterId)return;const form=collectBuildForm();buildRuntime.formDraft={characterId:String(state.ui.buildCharacterId),...form};const profile=resolvedBuildProfile(characterDetail,form.context);buildRuntime.artifactRanks=rankArtifactSets(catalog?.artifacts||[],profile);if(buildRuntime.weaponCandidates.length)buildRuntime.weaponRanks=rankWeapons(buildRuntime.weaponCandidates,profile,ownedWeaponNames());latestBuildResult=null;render()}
document.addEventListener('change',async event=>{const id=event.target?.id;if(id==='farm-server'){state.ui.farmServer=event.target.value||'Asia';persist();render();return}if(id==='team-mode'){state.ui.teamMode=event.target.value;state.ui.teamLock1='';state.ui.teamLock2='';teamRuntime={result:null,error:''};persist();render();return}if(id==='team-lock-1'){state.ui.teamLock1=event.target.value;teamRuntime={result:null,error:''};persist();render();return}if(id==='team-lock-2'){state.ui.teamLock2=event.target.value;teamRuntime={result:null,error:''};persist();render();return}if(id==='team-allow-unowned'){state.ui.teamAllowUnowned=Boolean(event.target.checked);teamRuntime={result:null,error:''};persist();render();return}if(id==='modal-char'){const existing=state.roster.find(x=>String(x.id)===String(event.target.value))||null;rosterModal(existing,event.target.value);return}if(event.target?.dataset?.buildContext){refreshBuildContext();return}if(id==='filter-element'){state.ui.element=event.target.value;state.ui.page=1;persist();render()}if(id==='filter-weapon'){state.ui.weapon=event.target.value;state.ui.page=1;persist();render()}if(id==='filter-rarity'){state.ui.rarity=event.target.value.replace('★','');state.ui.page=1;persist();render()}if(id==='build-character'){state.ui.buildCharacterId=event.target.value;characterDetail=null;latestBuildResult=null;buildRuntime={weaponCandidates:[],weaponRanks:[],artifactRanks:[],loadingWeapons:false,formDraft:null};persist();render()}if(id==='restore-file'&&event.target.files?.[0]){try{const text=await event.target.files[0].text();state=importState(text);persist();toast('Backup restored.');render()}catch(e){toast(e.message)}}})
window.addEventListener('dblclick',e=>e.preventDefault(),{passive:false});for(const evt of['gesturestart','gesturechange','gestureend'])document.addEventListener(evt,e=>e.preventDefault(),{passive:false});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./service-worker.js').catch(()=>{}));
async function init(){render();try{catalog=await loadCatalog();state.roster=normalizeRoster(state.roster,catalog.characters);persist();sourceStatus=catalog.warning?'warn':'ready'}catch(e){sourceStatus='error';toast(e.message)}render()}init();
